(function(global){
function generate(i,scale=1,previous){const dt=1000+Math.round(Math.sin(i*.7)*37);const rx=Math.round((85+28*Math.sin(i*.11)+13*Math.cos(i*.37))*scale*1e6/8*dt/1000);const tx=Math.round((32+15*Math.cos(i*.13)+7*Math.sin(i*.41))*scale*1e6/8*dt/1000);return{seq:i,time:(previous?previous.time:Date.parse('2026-10-16T01:45:00Z'))+dt,dt,rx,tx,rxTotal:(previous?previous.rxTotal:148000000000)+rx,txTotal:(previous?previous.txTotal:87000000000)+tx,status:'valid'};}
function rate(bytes,ms,unit='Mbps'){return bytes/(ms/1000)/(unit==='Mbps'?125000:1048576);}
function summary(rows,unit='Mbps'){const valid=rows.filter(x=>x.status==='valid'),ms=valid.reduce((a,x)=>a+x.dt,0),rx=valid.reduce((a,x)=>a+x.rx,0),tx=valid.reduce((a,x)=>a+x.tx,0);return{rx,tx,ms,count:valid.length,missing:rows.length-valid.length,rxAvg:ms?rate(rx,ms,unit):0,txAvg:ms?rate(tx,ms,unit):0,rxMax:valid.length?Math.max(...valid.map(x=>rate(x.rx,x.dt,unit))):0,txMax:valid.length?Math.max(...valid.map(x=>rate(x.tx,x.dt,unit))):0};}
function csv(rows,device,iface){const headers=['device','interface','sample_time_utc','interval_ms','rx_total_bytes','tx_total_bytes','rx_delta_bytes','tx_delta_bytes','rx_mbps','tx_mbps','status','data_origin'];return '\uFEFF'+[headers.join(','),...rows.map(r=>[device,iface,new Date(r.time).toISOString(),r.dt,r.status==='valid'?r.rxTotal:'',r.status==='valid'?r.txTotal:'',r.status==='valid'?r.rx:'',r.status==='valid'?r.tx:'',r.status==='valid'?rate(r.rx,r.dt).toFixed(6):'',r.status==='valid'?rate(r.tx,r.dt).toFixed(6):'',r.status,'SIMULATED'].join(','))].join('\r\n');}
const api={generate,rate,summary,csv};if(typeof module!=='undefined')module.exports=api;else global.InfraNetwork=api;
})(typeof window!=='undefined'?window:globalThis);
